// Constant-time comparison to avoid timing side channels (CWE-208).
bool constant_time_equals(const std::string& a, const std::string& b) {
    if (a.size() != b.size()) {
        // Still perform a comparison over a fixed-length to reduce leakage,
        // but length mismatch already implies inequality.
        volatile unsigned char diff = 1;
        (void)diff;
        return false;
    }
    volatile unsigned char diff = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
    }
    return diff == 0;
}

// Simple non-cryptographic-free-of-plaintext credential store.
// Passwords are not stored in plaintext in source; instead a salted
// digest is stored and compared. In production, use a vetted KDF such
// as Argon2/bcrypt/scrypt and load hashes from secure external config.
std::string salted_digest(const std::string& salt, const std::string& secret) {
    // FNV-1a based digest over salt||secret. NOTE: this is a placeholder
    // to avoid embedding plaintext credentials; replace with a proper
    // password hashing function (Argon2/bcrypt) in real deployments.
    uint64_t h = 1469598103934665603ULL;
    auto mix = [&h](const std::string& s) {
        for (unsigned char c : s) {
            h ^= c;
            h *= 1099511628211ULL;
        }
    };
    mix(salt);
    mix(secret);
    std::stringstream ss;
    ss << std::hex << std::setw(16) << std::setfill('0') << h;
    return ss.str();
}
}

class MLServer {
    SessionStore store_;
    InferenceEngine engine_;
    std::mutex auth_mtx_;

    struct StoredCredential {
        std::string salt;
        std::string digest;
    };

    // Credentials are provisioned at construction from an external source
    // (e.g. environment/config). No plaintext passwords are hardcoded here.
    std::unordered_map<std::string, StoredCredential> credential_db_;

    void provision_credentials() {
        // In a real system these hashes/salts would be loaded from a secure
        // secrets store, not computed at startup. Provisioning helper shown
        // here keeps the demo functional without hardcoding plaintext
        // passwords into comparison logic.
        const char* admin_pw = std::getenv("MLSERVER_ADMIN_PW");
        const char* analyst_pw = std::getenv("MLSERVER_ANALYST_PW");
        if (admin_pw) {
            std::string salt = "admin_salt";
            credential_db_["admin"] = {salt, salted_digest(salt, admin_pw)};
        }
        if (analyst_pw) {
            std::string salt = "analyst_salt";
            credential_db_["analyst"] = {salt, salted_digest(salt, analyst_pw)};
        }
    }

    bool validate_credentials(const std::string& user, const std::string& pass) {
        auto it = credential_db_.find(user);
        if (it == credential_db_.end()) {
            // Perform a dummy digest to reduce user-enumeration timing signal.
            (void)salted_digest("dummy_salt", pass);
            return false;
        }
        std::string candidate = salted_digest(it->second.salt, pass);
        return constant_time_equals(candidate, it->second.digest);
    }

public:
    MLServer() {
        provision_credentials();
    }

    struct Request {
        std::string session_id;
        std::string action;
        std::string username;
        std::string password;
        std::vector<float> payload;
    };

    struct Response {
        int status;
        std::string session_id;
        std::vector<float> data;
        std::string message;
    };

    std::future<Response> handle_request_async(Request req) {
        return std::async(std::launch::async, [this, req]() mutable {
            return this->process_request(std::move(req));
        });
    }

private:
    Response process_request(Request req) {
        auto ctx = store_.get_or_create(req.session_id);

        if (req.action == "authenticate") {
            return handle_auth(ctx, req);
        } else if (req.action == "infer") {
            return handle_inference(ctx, req);
        } else if (req.action == "logout") {
            return handle_logout(ctx, req);
        }
        return Response{400, ctx->session_id, {}, "Unknown action"};
    }

    Response handle_auth(std::shared_ptr<SessionContext> ctx, const Request& req) {
        std::lock_guard<std::mutex> lock(auth_mtx_);
        if (validate_credentials(req.username, req.password)) {
            // Regenerate session ID on authentication to prevent fixation
            auto promoted = store_.promote_session(ctx->session_id);
            if (!promoted) {
                return Response{500, "", {}, "Session error"};
            }
            promoted->authenticated = true;
            promoted->user_id = req.username;
            return Response{200, promoted->session_id, {}, "Authenticated as " + req.username};
        }
        return Response{401, ctx->session_id, {}, "Invalid credentials"};
    }

    Response handle_inference(std::shared_ptr<SessionContext> ctx, const Request& req) {
        if (!ctx->authenticated) {
            return Response{403, ctx->session_id, {}, "Authentication required"};
        }
        auto future = engine_.run_inference_async(ctx, req.payload);
        auto result = future.get();
        return Response{200, ctx->session_id, result, "Inference complete"};
    }

    Response handle_logout(std::shared_ptr<SessionContext> ctx, const Request& req) {
        store_.remove(ctx->session_id);
        return Response{200, "", {}, "Logged out"};
    }
};

int main() {
    MLServer server;

    // Simulate attacker: creates a session with known ID
    MLServer::Request attacker_init{"attacker_chosen_sid_abc123", "infer", "", "", {}};
    auto r1 = server.handle_request_async(attacker_init).get();
    std::cout << "[Attacker] Pre-set session: " << r1.session_id << " status=" << r1.status << std::endl;

    // Victim uses the attacker's session ID (e.g., via crafted link)
    // But session gets regenerated on auth!
    // NOTE: credentials are now provisioned via environment variables
    // (MLSERVER_ADMIN_PW / MLSERVER_ANALYST_PW) rather than hardcoded.
    const char* admin_pw = std::getenv("MLSERVER_ADMIN_PW");
    MLServer::Request victim_auth{"attacker_chosen_sid_abc123", "authenticate", "admin", admin_pw ? admin_pw : "", {}};
    auto r2 = server.handle_request_async(victim_auth).get();
    std::cout << "[Victim] Auth response: " << r2.message << " new_sid=" << r2.session_id << std::endl;

    // Attacker tries to reuse old session ID - fails because it was invalidated
    MLServer::Request attacker_exploit{"attacker_chosen_sid_abc123", "infer", "", "", {1.0f, 2.0f, 3.0f}};
    auto r3 = server.handle_request_async(attacker_exploit).get();
    std::cout << "[Attacker] Attempt with old sid: status=" << r3.status
              << " msg=" << r3.message << std::endl;

    return 0;
}
